# Thin UI: open classified Inspiration from Capture and edit it in-place.
write("src/components/CapturePanel.tsx", 'import { useEffect, useState } from "react";\nimport { InspirationPanel } from "./InspirationPanel";\nimport { SeedDevelopmentPanel } from "./SeedDevelopmentPanel";\nimport { TopicPanel } from "./TopicPanel";\nimport type { CaptureRole, CaptureSource, SourceType } from "../domain/types";\nimport { errorMessage } from "../domain/types";\nimport {\n  classifyCaptureSource,\n  createCaptureSource,\n  getCaptureSource,\n  listUnclassifiedCaptures,\n} from "../lib/workloreApi";\nimport "../capture.css";\n\nconst CAPTURE_SOURCE_TYPES: Array<{ value: SourceType; label: string }> = [\n  { value: "other", label: "Note or pasted text" },\n  { value: "job_description", label: "Job description" },\n  { value: "writing_sample", label: "Writing sample" },\n];\n\nconst CAPTURE_ROLES: Array<{ value: CaptureRole; label: string }> = [\n  { value: "story_seed", label: "Story seed" },\n  { value: "proof_point", label: "Proof point" },\n  { value: "topic_candidate", label: "Topic idea" },\n  { value: "inspiration", label: "Inspiration" },\n  { value: "target_context", label: "Target context" },\n];\n\nexport function CapturePanel({ vaultPath }: { vaultPath: string }) {\n  const [text, setText] = useState("");\n  const [sourceType, setSourceType] = useState<SourceType>("other");\n  const [saved, setSaved] = useState<CaptureSource | null>(null);\n  const [recent, setRecent] = useState<CaptureSource[]>([]);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [notice, setNotice] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [developmentSeedId, setDevelopmentSeedId] = useState<string | null>(null);\n  const [developmentTopicId, setDevelopmentTopicId] = useState<string | null>(null);\n  const [developmentInspirationId, setDevelopmentInspirationId] = useState<string | null>(null);\n\n  useEffect(() => {\n    setSaved(null);\n    setNotice(null);\n    setError(null);\n    setDevelopmentSeedId(null);\n    setDevelopmentTopicId(null);\n    setDevelopmentInspirationId(null);\n    void refreshRecent();\n  }, [vaultPath]);\n\n  async function refreshRecent() {\n    try {\n      setRecent(await listUnclassifiedCaptures(vaultPath, 8));\n    } catch (caught) {\n      setError(errorMessage(caught));\n    }\n  }\n\n  async function handleSave() {\n    if (!text.trim()) {\n      return;\n    }\n    setBusy("Saving capture");\n    setNotice(null);\n    setError(null);\n    try {\n      const created = await createCaptureSource(vaultPath, text, sourceType);\n      setSaved(created);\n      setText("");\n      setNotice("Saved locally. Classification is optional and happens after save.");\n      await refreshRecent();\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function handleClassify(role: CaptureRole) {\n    if (!saved) {\n      return;\n    }\n    setBusy("Connecting capture");\n    setNotice(null);\n    setError(null);\n    try {\n      const result = await classifyCaptureSource(vaultPath, saved.sourceId, role);\n      setSaved(await getCaptureSource(vaultPath, saved.sourceId));\n      setNotice(\n        result.created\n          ? `Connected as ${roleLabel(role)}.`\n          : `This capture is already connected as ${roleLabel(role)}.`,\n      );\n      await refreshRecent();\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function handleSelectRecent(sourceId: string) {\n    setBusy("Opening capture");\n    setError(null);\n    try {\n      setSaved(await getCaptureSource(vaultPath, sourceId));\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  const storySeedClassification = saved?.classifications.find(\n    (classification) => classification.role === "story_seed",\n  );\n  const topicClassification = saved?.classifications.find(\n    (classification) => classification.role === "topic_candidate",\n  );\n  const inspirationClassification = saved?.classifications.find(\n    (classification) => classification.role === "inspiration",\n  );\n\n  return (\n    <section className="workspace-panel capture-panel" aria-labelledby="capture-heading">\n      <div className="panel-heading-row capture-heading-row">\n        <div>\n          <p className="eyebrow">Capture</p>\n          <h2 id="capture-heading">Save it before you sort it</h2>\n          <p className="capture-intro">\n            Paste a memory, result, idea, question, URL, excerpt, job description, writing sample,\n            or note. WorkLore saves the original text first. Classification is optional.\n          </p>\n        </div>\n        <select\n          aria-label="Capture source type"\n          value={sourceType}\n          onChange={(event) => setSourceType(event.target.value as SourceType)}\n        >\n          {CAPTURE_SOURCE_TYPES.map((option) => (\n            <option key={option.value} value={option.value}>\n              {option.label}\n            </option>\n          ))}\n        </select>\n      </div>\n\n      <textarea\n        className="capture-input"\n        aria-label="Capture text"\n        placeholder="What happened, what did you notice, or what should future-you remember? For a URL-only Inspiration, paste the URL here first."\n        value={text}\n        onChange={(event) => setText(event.target.value)}\n        rows={6}\n      />\n      <div className="capture-save-row">\n        <button\n          className="primary-button"\n          disabled={!text.trim() || busy !== null}\n          onClick={() => void handleSave()}\n        >\n          Save capture\n        </button>\n        <span className="capture-save-rule">No AI or classification is required to save.</span>\n      </div>\n\n      {saved ? (\n        <div className="capture-saved-card">\n          <div className="capture-saved-heading">\n            <div>\n              <span className="status-pill">Saved</span>\n              <h3>{saved.displayName}</h3>\n              <p>{saved.sourceId}</p>\n            </div>\n            <button className="quiet-button compact" onClick={() => setSaved(null)}>\n              Done\n            </button>\n          </div>\n          <p className="capture-preview">{saved.text}</p>\n          <div className="capture-classify">\n            <strong>Optional connections</strong>\n            <div className="capture-classify-actions">\n              {CAPTURE_ROLES.map((option) => {\n                const linked = saved.classifications.some(\n                  (classification) => classification.role === option.value,\n                );\n                return (\n                  <button\n                    className={linked ? "quiet-button compact" : "secondary-button compact"}\n                    disabled={linked || busy !== null}\n                    key={option.value}\n                    onClick={() => void handleClassify(option.value)}\n                  >\n                    {linked ? `${option.label} linked` : option.label}\n                  </button>\n                );\n              })}\n            </div>\n            <p className="capture-source-only">\n              Leave it alone to keep this as Source-only material. External Inspiration does not\n              become Evidence or Voice Evidence here.\n            </p>\n            {storySeedClassification ? (\n              <button\n                className="primary-button compact"\n                disabled={busy !== null}\n                onClick={() => setDevelopmentSeedId(storySeedClassification.targetId)}\n              >\n                Develop this story seed\n              </button>\n            ) : null}\n            {topicClassification ? (\n              <button\n                className="primary-button compact"\n                disabled={busy !== null}\n                onClick={() => setDevelopmentTopicId(topicClassification.targetId)}\n              >\n                Open this topic\n              </button>\n            ) : null}\n            {inspirationClassification ? (\n              <button\n                className="primary-button compact"\n                disabled={busy !== null}\n                onClick={() => setDevelopmentInspirationId(inspirationClassification.targetId)}\n              >\n                Work with this inspiration\n              </button>\n            ) : null}\n          </div>\n        </div>\n      ) : null}\n\n      {developmentSeedId ? (\n        <SeedDevelopmentPanel\n          vaultPath={vaultPath}\n          seedId={developmentSeedId}\n          onClose={() => setDevelopmentSeedId(null)}\n        />\n      ) : null}\n\n      {developmentTopicId ? (\n        <TopicPanel\n          vaultPath={vaultPath}\n          topicId={developmentTopicId}\n          onClose={() => setDevelopmentTopicId(null)}\n        />\n      ) : null}\n\n      {developmentInspirationId ? (\n        <InspirationPanel\n          vaultPath={vaultPath}\n          inspirationId={developmentInspirationId}\n          onClose={() => setDevelopmentInspirationId(null)}\n        />\n      ) : null}\n\n      <div className="capture-feedback" aria-live="polite">\n        {busy ? <span>{busy}...</span> : null}\n        {notice ? <span className="capture-notice">{notice}</span> : null}\n        {error ? <span className="capture-error">{error}</span> : null}\n      </div>\n\n      {recent.length > 0 ? (\n        <div className="capture-recent">\n          <div className="capture-recent-heading">\n            <h3>Recent unclassified captures</h3>\n            <span>{recent.length} shown</span>\n          </div>\n          <div className="capture-recent-list">\n            {recent.map((capture) => (\n              <button\n                className="capture-recent-item"\n                key={capture.sourceId}\n                onClick={() => void handleSelectRecent(capture.sourceId)}\n              >\n                <strong>{capture.displayName}</strong>\n                <span>{formatDate(capture.createdAt)}</span>\n              </button>\n            ))}\n          </div>\n        </div>\n      ) : null}\n    </section>\n  );\n}\n\nfunction roleLabel(role: CaptureRole): string {\n  return CAPTURE_ROLES.find((option) => option.value === role)?.label.toLowerCase() ?? role;\n}\n\nfunction formatDate(value: string): string {\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) {\n    return value;\n  }\n  return new Intl.DateTimeFormat("en-US", {\n    dateStyle: "medium",\n    timeStyle: "short",\n  }).format(date);\n}\n')
write("src/components/InspirationPanel.tsx", 'import { useEffect, useMemo, useState } from "react";\nimport type {\n  InspirationLifecycle,\n  InspirationLinkTarget,\n  InspirationRecord,\n  InspirationRelationKind,\n} from "../domain/types";\nimport { errorMessage } from "../domain/types";\nimport {\n  addInspirationRelationship,\n  getInspiration,\n  listInspirationLinkTargets,\n  removeInspirationRelationship,\n  updateInspiration,\n} from "../lib/workloreApi";\nimport "../inspiration.css";\n\nconst LIFECYCLES: Array<{ value: InspirationLifecycle; label: string }> = [\n  { value: "saved", label: "Saved" },\n  { value: "processed", label: "Processed" },\n  { value: "archived", label: "Archived" },\n];\n\nconst RELATION_KINDS: Array<{ value: InspirationRelationKind; label: string }> = [\n  { value: "topic", label: "Topic" },\n  { value: "theme", label: "Theme" },\n];\n\nexport function InspirationPanel({\n  vaultPath,\n  inspirationId,\n  onClose,\n}: {\n  vaultPath: string;\n  inspirationId: string;\n  onClose: () => void;\n}) {\n  const [record, setRecord] = useState<InspirationRecord | null>(null);\n  const [title, setTitle] = useState("");\n  const [lifecycle, setLifecycle] = useState<InspirationLifecycle>("saved");\n  const [sourceUrl, setSourceUrl] = useState("");\n  const [sourceTitle, setSourceTitle] = useState("");\n  const [sourceAuthor, setSourceAuthor] = useState("");\n  const [sourcePublishedAt, setSourcePublishedAt] = useState("");\n  const [summary, setSummary] = useState("");\n  const [takeaways, setTakeaways] = useState("");\n  const [excerpts, setExcerpts] = useState("");\n  const [whyInteresting, setWhyInteresting] = useState("");\n  const [userReaction, setUserReaction] = useState("");\n  const [concepts, setConcepts] = useState("");\n  const [questions, setQuestions] = useState("");\n  const [counterpoints, setCounterpoints] = useState("");\n  const [notes, setNotes] = useState("");\n  const [relationKind, setRelationKind] = useState<InspirationRelationKind>("topic");\n  const [targetId, setTargetId] = useState("");\n  const [targets, setTargets] = useState<Record<InspirationRelationKind, InspirationLinkTarget[]>>({\n    topic: [],\n    theme: [],\n  });\n  const [busy, setBusy] = useState<string | null>(null);\n  const [notice, setNotice] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    void refreshAll();\n  }, [vaultPath, inspirationId]);\n\n  async function refreshAll() {\n    setBusy("Opening inspiration");\n    setError(null);\n    try {\n      const [loaded, topicTargets, themeTargets] = await Promise.all([\n        getInspiration(vaultPath, inspirationId),\n        listInspirationLinkTargets(vaultPath, "topic"),\n        listInspirationLinkTargets(vaultPath, "theme"),\n      ]);\n      applyRecord(loaded);\n      setTargets({ topic: topicTargets, theme: themeTargets });\n      setTargetId("");\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  function applyRecord(loaded: InspirationRecord) {\n    setRecord(loaded);\n    setTitle(loaded.title);\n    setLifecycle(loaded.lifecycle);\n    setSourceUrl(loaded.sourceUrl ?? "");\n    setSourceTitle(loaded.sourceTitle ?? "");\n    setSourceAuthor(loaded.sourceAuthor ?? "");\n    setSourcePublishedAt(loaded.sourcePublishedAt ?? "");\n    setSummary(loaded.summary);\n    setTakeaways(linesFrom(loaded.takeaways));\n    setExcerpts(\n      loaded.excerpts\n        .map((excerpt) => `${excerpt.locator ? `${excerpt.locator} | ` : ""}${excerpt.text}`)\n        .join("\\n"),\n    );\n    setWhyInteresting(loaded.whyInteresting);\n    setUserReaction(loaded.userReaction);\n    setConcepts(linesFrom(loaded.concepts));\n    setQuestions(linesFrom(loaded.questions));\n    setCounterpoints(linesFrom(loaded.counterpoints));\n    setNotes(loaded.notes);\n  }\n\n  async function handleSave() {\n    if (!record || !title.trim()) {\n      return;\n    }\n    setBusy("Saving inspiration");\n    setNotice(null);\n    setError(null);\n    try {\n      const updated = await updateInspiration(vaultPath, {\n        inspirationId: record.inspirationId,\n        title,\n        lifecycle,\n        sourceUrl: sourceUrl || null,\n        sourceTitle: sourceTitle || null,\n        sourceAuthor: sourceAuthor || null,\n        sourcePublishedAt: sourcePublishedAt || null,\n        summary,\n        takeaways: listFrom(takeaways),\n        excerpts: excerptInputsFrom(excerpts),\n        whyInteresting,\n        userReaction,\n        concepts: listFrom(concepts),\n        questions: listFrom(questions),\n        counterpoints: listFrom(counterpoints),\n        notes,\n      });\n      applyRecord(updated);\n      setNotice("Inspiration saved locally. External wording remains attributed to its Source.");\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function handleAddRelationship() {\n    if (!record || !targetId) {\n      return;\n    }\n    setBusy("Connecting inspiration");\n    setNotice(null);\n    setError(null);\n    try {\n      const result = await addInspirationRelationship(\n        vaultPath,\n        record.inspirationId,\n        relationKind,\n        targetId,\n      );\n      setNotice(result.changed ? "Connection added." : "That connection already exists.");\n      await refreshAll();\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function handleRemoveRelationship(kind: InspirationRelationKind, relatedId: string) {\n    if (!record) {\n      return;\n    }\n    setBusy("Removing connection");\n    setNotice(null);\n    setError(null);\n    try {\n      await removeInspirationRelationship(vaultPath, record.inspirationId, kind, relatedId);\n      setNotice("Connection removed; both records were kept.");\n      await refreshAll();\n    } catch (caught) {\n      setError(errorMessage(caught));\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  const linkedTargetIds = useMemo(\n    () => new Set(record?.relationships.map((relationship) => relationship.targetId) ?? []),\n    [record],\n  );\n  const availableTargets = targets[relationKind].filter(\n    (target) => !linkedTargetIds.has(target.targetId),\n  );\n\n  return (\n    <section className="inspiration-panel" aria-labelledby="inspiration-panel-heading">\n      <div className="inspiration-heading-row">\n        <div>\n          <p className="eyebrow">Inspiration</p>\n          <h3 id="inspiration-panel-heading">Keep the source, keep your reaction separate</h3>\n          <p>\n            External material can shape an idea without becoming evidence about you or silently\n            becoming your voice.\n          </p>\n        </div>\n        <button className="quiet-button compact" onClick={onClose}>Close</button>\n      </div>\n\n      {record ? (\n        <>\n          <div className="inspiration-provenance">\n            <strong>Source provenance</strong>\n            {record.source ? (\n              <>\n                <span>{record.source.displayName}</span>\n                <span>{record.source.sourceId} · {record.source.sourceOrigin}</span>\n                {record.source.originalFileName ? <span>{record.source.originalFileName}</span> : null}\n                {record.source.sourceUrl ? <span>{record.source.sourceUrl}</span> : null}\n              </>\n            ) : (\n              <span>No Source is attached to this legacy Inspiration.</span>\n            )}\n          </div>\n\n          <div className="inspiration-editor-grid">\n            <label>\n              Title\n              <input value={title} onChange={(event) => setTitle(event.target.value)} />\n            </label>\n            <label>\n              Lifecycle\n              <select\n                value={lifecycle}\n                onChange={(event) => setLifecycle(event.target.value as InspirationLifecycle)}\n              >\n                {LIFECYCLES.map((option) => (\n                  <option key={option.value} value={option.value}>{option.label}</option>\n                ))}\n              </select>\n            </label>\n            <label className="inspiration-wide">\n              Source URL\n              <input\n                value={sourceUrl}\n                onChange={(event) => setSourceUrl(event.target.value)}\n                placeholder="https://…"\n              />\n            </label>\n            <label>\n              Source title\n              <input value={sourceTitle} onChange={(event) => setSourceTitle(event.target.value)} />\n            </label>\n            <label>\n              Author\n              <input value={sourceAuthor} onChange={(event) => setSourceAuthor(event.target.value)} />\n            </label>\n            <label>\n              Published\n              <input\n                type="date"\n                value={sourcePublishedAt}\n                onChange={(event) => setSourcePublishedAt(event.target.value)}\n              />\n            </label>\n            <label className="inspiration-wide">\n              Summary\n              <textarea rows={4} value={summary} onChange={(event) => setSummary(event.target.value)} />\n            </label>\n            <label className="inspiration-wide">\n              Main takeaways\n              <textarea\n                rows={4}\n                value={takeaways}\n                onChange={(event) => setTakeaways(event.target.value)}\n                placeholder="One takeaway per line"\n              />\n            </label>\n            <label className="inspiration-wide">\n              Useful excerpts\n              <textarea\n                rows={4}\n                value={excerpts}\n                onChange={(event) => setExcerpts(event.target.value)}\n                placeholder="Optional locator | verbatim excerpt"\n              />\n              <small>These remain attributed to the attached Source.</small>\n            </label>\n            <label className="inspiration-wide">\n              Why is this interesting?\n              <textarea\n                rows={3}\n                value={whyInteresting}\n                onChange={(event) => setWhyInteresting(event.target.value)}\n              />\n            </label>\n            <label className="inspiration-wide inspiration-reaction">\n              My reaction\n              <textarea\n                rows={4}\n                value={userReaction}\n                onChange={(event) => setUserReaction(event.target.value)}\n                placeholder="What do you agree with, reject, extend, or want to test?"\n              />\n              <small>User-authored, but not automatically Voice Evidence.</small>\n            </label>\n            <label>\n              Possible concepts / angles\n              <textarea\n                rows={5}\n                value={concepts}\n                onChange={(event) => setConcepts(event.target.value)}\n                placeholder="One per line"\n              />\n            </label>\n            <label>\n              Questions\n              <textarea\n                rows={5}\n                value={questions}\n                onChange={(event) => setQuestions(event.target.value)}\n                placeholder="One per line"\n              />\n            </label>\n            <label>\n              Counterpoints\n              <textarea\n                rows={5}\n                value={counterpoints}\n                onChange={(event) => setCounterpoints(event.target.value)}\n                placeholder="One per line"\n              />\n            </label>\n            <label className="inspiration-wide">\n              Notes\n              <textarea rows={4} value={notes} onChange={(event) => setNotes(event.target.value)} />\n            </label>\n          </div>\n\n          <div className="inspiration-actions-row">\n            <button\n              className="primary-button compact"\n              disabled={busy !== null || !title.trim()}\n              onClick={() => void handleSave()}\n            >\n              Save inspiration\n            </button>\n            <span>{record.inspirationId}</span>\n          </div>\n\n          <div className="inspiration-connections">\n            <div>\n              <h4>Connections</h4>\n              <p>Topics and Themes organize this external context. They do not turn it into standing.</p>\n            </div>\n            {record.relationships.length === 0 ? (\n              <span className="inspiration-empty">No Topic or Theme connections yet.</span>\n            ) : null}\n            {record.relationships.map((relationship) => (\n              <div className="inspiration-link-row" key={relationship.relationshipId}>\n                <div>\n                  <strong>{relationship.targetLabel}</strong>\n                  <span>{kindLabel(relationship.relationKind)} · {relationship.targetStatus}</span>\n                </div>\n                <button\n                  className="quiet-button compact"\n                  onClick={() =>\n                    void handleRemoveRelationship(\n                      relationship.relationKind,\n                      relationship.targetId,\n                    )\n                  }\n                >\n                  Remove\n                </button>\n              </div>\n            ))}\n            <div className="inspiration-connect-row">\n              <select\n                value={relationKind}\n                onChange={(event) => {\n                  setRelationKind(event.target.value as InspirationRelationKind);\n                  setTargetId("");\n                }}\n              >\n                {RELATION_KINDS.map((option) => (\n                  <option key={option.value} value={option.value}>{option.label}</option>\n                ))}\n              </select>\n              <select value={targetId} onChange={(event) => setTargetId(event.target.value)}>\n                <option value="">Select an existing {kindLabel(relationKind).toLowerCase()}</option>\n                {availableTargets.map((target) => (\n                  <option key={target.targetId} value={target.targetId}>{target.label}</option>\n                ))}\n              </select>\n              <button\n                className="secondary-button compact"\n                disabled={!targetId || busy !== null}\n                onClick={() => void handleAddRelationship()}\n              >\n                Connect\n              </button>\n            </div>\n          </div>\n        </>\n      ) : null}\n\n      <div className="inspiration-feedback" aria-live="polite">\n        {busy ? <span>{busy}...</span> : null}\n        {notice ? <span>{notice}</span> : null}\n        {error ? <span className="capture-error">{error}</span> : null}\n      </div>\n    </section>\n  );\n}\n\nfunction linesFrom(values: string[]): string {\n  return values.join("\\n");\n}\n\nfunction listFrom(value: string): string[] {\n  return value\n    .split(/\\r?\\n/)\n    .map((line) => line.trim())\n    .filter(Boolean);\n}\n\nfunction excerptInputsFrom(value: string): Array<{ text: string; locator: string }> {\n  return value\n    .split(/\\r?\\n/)\n    .map((line) => line.trim())\n    .filter(Boolean)\n    .map((line) => {\n      const separator = line.indexOf("|");\n      if (separator < 0) {\n        return { text: line, locator: "" };\n      }\n      return {\n        locator: line.slice(0, separator).trim(),\n        text: line.slice(separator + 1).trim(),\n      };\n    })\n    .filter((excerpt) => excerpt.text.length > 0);\n}\n\nfunction kindLabel(kind: InspirationRelationKind): string {\n  return RELATION_KINDS.find((option) => option.value === kind)?.label ?? kind;\n}\n')
write("src/inspiration.css", '.inspiration-panel {\n  border-top: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.14));\n  margin-top: 1rem;\n  padding-top: 1rem;\n}\n\n.inspiration-heading-row,\n.inspiration-actions-row,\n.inspiration-connect-row,\n.inspiration-link-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.75rem;\n}\n\n.inspiration-heading-row {\n  align-items: flex-start;\n}\n\n.inspiration-heading-row h3,\n.inspiration-connections h4 {\n  margin: 0;\n}\n\n.inspiration-heading-row p,\n.inspiration-connections p {\n  margin: 0.35rem 0 0;\n  color: var(--text-muted, #a8b3bd);\n}\n\n.inspiration-provenance {\n  display: grid;\n  gap: 0.25rem;\n  margin: 1rem 0;\n  padding: 0.8rem;\n  border: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.14));\n  border-radius: 0.75rem;\n  background: rgba(8, 18, 28, 0.35);\n}\n\n.inspiration-provenance span {\n  color: var(--text-muted, #a8b3bd);\n  overflow-wrap: anywhere;\n}\n\n.inspiration-editor-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 0.8rem;\n}\n\n.inspiration-editor-grid label {\n  display: grid;\n  gap: 0.35rem;\n  font-size: 0.9rem;\n  font-weight: 600;\n}\n\n.inspiration-editor-grid input,\n.inspiration-editor-grid select,\n.inspiration-editor-grid textarea,\n.inspiration-connect-row select {\n  width: 100%;\n}\n\n.inspiration-editor-grid small {\n  color: var(--text-muted, #a8b3bd);\n  font-weight: 400;\n}\n\n.inspiration-wide {\n  grid-column: 1 / -1;\n}\n\n.inspiration-reaction {\n  padding: 0.7rem;\n  border-left: 3px solid rgba(255, 255, 255, 0.28);\n  background: rgba(8, 18, 28, 0.35);\n}\n\n.inspiration-actions-row {\n  margin-top: 1rem;\n  justify-content: flex-start;\n}\n\n.inspiration-actions-row span {\n  color: var(--text-muted, #a8b3bd);\n  font-size: 0.82rem;\n}\n\n.inspiration-connections {\n  display: grid;\n  gap: 0.65rem;\n  margin-top: 1rem;\n  padding-top: 1rem;\n  border-top: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.14));\n}\n\n.inspiration-link-row {\n  padding: 0.65rem 0;\n  border-bottom: 1px solid var(--border-subtle, rgba(255, 255, 255, 0.14));\n}\n\n.inspiration-link-row div {\n  display: grid;\n  gap: 0.2rem;\n}\n\n.inspiration-link-row span,\n.inspiration-empty {\n  color: var(--text-muted, #a8b3bd);\n  font-size: 0.85rem;\n}\n\n.inspiration-connect-row {\n  justify-content: flex-start;\n}\n\n.inspiration-connect-row select {\n  max-width: 20rem;\n}\n\n.inspiration-feedback {\n  min-height: 1.4rem;\n  margin-top: 0.75rem;\n  color: var(--text-muted, #a8b3bd);\n}\n\n@media (max-width: 760px) {\n  .inspiration-editor-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .inspiration-wide {\n    grid-column: auto;\n  }\n\n  .inspiration-connect-row,\n  .inspiration-heading-row {\n    align-items: stretch;\n    flex-direction: column;\n  }\n\n  .inspiration-connect-row select {\n    max-width: none;\n  }\n}\n')

